    ctx.fillStyle = INK; ctx.strokeStyle = INK; ctx.lineWidth = Math.max(0.9, s / 30); ctx.lineJoin = 'round'; ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
