    ctx.fillStyle = c; ctx.fillRect(cx - 66, cy - 27, 132, 4); ctx.fillRect(cx - 66, cy + 23, 132, 4);
    ctx.textAlign = 'center'; ctx.font = '25px ' + F.bold; ctx.fillText('ABADI', cx, cy - 10); ctx.fillText('MANDIRI', cx, cy + 14);
