    for (var i = 0; i < 160; i++) { var a = rnd() * 6.28, rr = rnd() * R; ctx.fillRect(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr, 1 + rnd() * 2.5, 1 + rnd() * 2.5); }
