    ctx.fillText('578301029535530', 0, 0); ctx.fillText('BADRUL MUNIR', 0, 38); ctx.fillText('BRI', 0, 76);
    ctx.fillStyle = 'rgba(246,246,249,.5)'; for (var i = 0; i < 120; i++) ctx.fillRect(rnd() * 270, -26 + rnd() * 110, 1 + rnd() * 2, 1 + rnd() * 2);
