      var hy = (T + HB) / 2 + 7;
      label(ctx, 'BANYAKNYA', (L + X1) / 2, hy, 17, false, 'center'); label(ctx, 'NAMA BARANG', (X1 + X2) / 2, hy, 21, false, 'center');
      label(ctx, 'HARGA', (X2 + X3) / 2, hy, 21, false, 'center'); label(ctx, 'JUMLAH', (X3 + R) / 2, hy, 21, false, 'center');

